import pandas as pd
from rdkit import Chem
from rdkit.Chem import Descriptors, rdMolDescriptors, AllChem
from rdkit.Chem import FilterCatalog
from rdkit.Chem.FilterCatalog import FilterCatalogParams, FilterCatalog
from rdkit import DataStructs

def _function(Dict: dict[str, pd.DataFrame]) -> pd.DataFrame:
    #---IMPORT LIBRARIES HERE---#
    # (imports done at top)
    #---CODE HERE---#

    def _get_mol(smiles):
        if not isinstance(smiles, str):
            return None
        try:
            return Chem.MolFromSmiles(smiles)
        except Exception:
            return None

    # Build PAINS / Brenk / NIH filter catalog
    params = FilterCatalogParams()
    for cat in [FilterCatalogParams.FilterCatalogs.PAINS,
                FilterCatalogParams.FilterCatalogs.BRENK,
                FilterCatalogParams.FilterCatalogs.NIH]:
        params.AddCatalog(cat)
    catalog = FilterCatalog(params)

    def _passes_filters(mol):
        if mol is None:
            return False
        try:
            return not catalog.HasMatch(mol)
        except Exception:
            return False

    def _calc_rot_bonds(mol):
        try:
            return rdMolDescriptors.CalcNumRotatableBonds(mol)
        except Exception:
            return None

    def _calc_formal_charge(mol):
        try:
            return Chem.GetFormalCharge(mol)
        except Exception:
            return None

    def _calc_sa(mol):
        # SA_Score implementation via sascorer if available
        try:
            from rdkit.Chem import RDConfig
            import os
            import sys
            sys.path.append(os.path.join(RDConfig.RDContribDir, 'SA_Score'))
            import sascorer
            return sascorer.calculateScore(mol)
        except Exception:
            return None

    def _tanimoto(mol, ref_mol):
        if mol is None or ref_mol is None:
            return None
        try:
            fp1 = AllChem.GetMorganFingerprintAsBitVect(mol, 2, nBits=2048)
            fp2 = AllChem.GetMorganFingerprintAsBitVect(ref_mol, 2, nBits=2048)
            return DataStructs.TanimotoSimilarity(fp1, fp2)
        except Exception:
            return None

    # Gather candidate frames
    candidates = []
    if 'MOL007' in Dict:
        candidates.append(Dict['MOL007'])
    if 'MOL008' in Dict:
        mol008 = Dict['MOL008']
        candidates.append(mol008.head(100))

    if not candidates:
        # Return empty frame with same columns if none present
        base_cols = ['HBA', 'HBD', 'LogP', 'MW', 'QED', 'SAScore', 'SMILES', 'Similarity', 'TPSA']
        return pd.DataFrame(columns=base_cols)

    combined = pd.concat(candidates, ignore_index=True)
    # Deduplicate by SMILES while preserving order
    if 'SMILES' in combined.columns:
        combined = combined.drop_duplicates(subset=['SMILES'], keep='first').reset_index(drop=True)

    # Determine reference ligand from MOL007
    ref_mol = None
    if 'MOL007' in Dict and len(Dict['MOL007']) > 0:
        ref_smiles_candidates = Dict['MOL007']['SMILES'].dropna().unique().tolist()
        for s in ref_smiles_candidates:
            m = _get_mol(s)
            if m is not None:
                ref_mol = m
                break

    ref_smiles_set = set()
    if 'MOL007' in Dict and 'SMILES' in Dict['MOL007'].columns:
        ref_smiles_set = set(Dict['MOL007']['SMILES'].dropna().tolist())

    passing_rows = []

    for _, row in combined.iterrows():
        smiles = row.get('SMILES', None)
        mol = _get_mol(smiles)

        is_reference = smiles in ref_smiles_set if isinstance(smiles, str) else False

        # Hard constraints (computable from columns or RDKit)
        mw = row.get('MW', None)
        logp = row.get('LogP', None)
        tpsa = row.get('TPSA', None)
        hbd = row.get('HBD', None)
        hba = row.get('HBA', None)
        sa = row.get('SAScore', None)

        # Compute missing values with RDKit where possible
        if mol is not None:
            try:
                if pd.isna(mw):
                    mw = Descriptors.MolWt(mol)
            except Exception:
                pass
            try:
                if pd.isna(logp):
                    logp = Descriptors.MolLogP(mol)
            except Exception:
                pass
            try:
                if pd.isna(tpsa):
                    tpsa = rdMolDescriptors.CalcTPSA(mol)
            except Exception:
                pass
            try:
                if pd.isna(hbd):
                    hbd = rdMolDescriptors.CalcNumHBD(mol)
            except Exception:
                pass
            try:
                if pd.isna(hba):
                    hba = rdMolDescriptors.CalcNumHBA(mol)
            except Exception:
                pass

        rot_bonds = _calc_rot_bonds(mol) if mol is not None else None
        formal_charge = _calc_formal_charge(mol) if mol is not None else None
        sa_score = sa if (sa is not None and not pd.isna(sa)) else _calc_sa(mol) if mol is not None else None
        tanimoto = _tanimoto(mol, ref_mol) if ref_mol is not None else row.get('Similarity', None)

        # Evaluate constraints
        ok = True

        # MW < 600
        if mw is not None and not pd.isna(mw):
            if not (mw < 600):
                ok = False
        # LogP -1 to 5
        if ok and logp is not None and not pd.isna(logp):
            if not (-1 <= logp <= 5):
                ok = False
        # TPSA < 140
        if ok and tpsa is not None and not pd.isna(tpsa):
            if not (tpsa < 140):
                ok = False
        # HBD <= 5
        if ok and hbd is not None and not pd.isna(hbd):
            if not (hbd <= 5):
                ok = False
        # HBA <= 10
        if ok and hba is not None and not pd.isna(hba):
            if not (hba <= 10):
                ok = False
        # rotatable bonds <= 10
        if ok and rot_bonds is not None:
            if not (rot_bonds <= 10):
                ok = False
        # formal charge -2 to +2
        if ok and formal_charge is not None:
            if not (-2 <= formal_charge <= 2):
                ok = False
        # SA score < 4.5
        if ok and sa_score is not None and not pd.isna(sa_score):
            if not (sa_score < 4.5):
                ok = False
        # PAINS/Brenk/NIH pass
        if ok:
            if not _passes_filters(mol):
                ok = False
        # Tanimoto >= 0.7 to MOL007 reference (unless this row IS the reference)
        if ok and not is_reference:
            if tanimoto is not None and not pd.isna(tanimoto):
                if not (tanimoto >= 0.7):
                    ok = False
            else:
                # Cannot calculate similarity - reject (except reference)
                ok = False

        if ok:
            new_row = row.copy()
            # Update computed values
            if mw is not None and not pd.isna(mw):
                new_row['MW'] = mw
            if logp is not None and not pd.isna(logp):
                new_row['LogP'] = logp
            if tpsa is not None and not pd.isna(tpsa):
                new_row['TPSA'] = tpsa
            if hbd is not None and not pd.isna(hbd):
                new_row['HBD'] = hbd
            if hba is not None and not pd.isna(hba):
                new_row['HBA'] = hba
            if tanimoto is not None and not pd.isna(tanimoto):
                new_row['Similarity'] = tanimoto
            passing_rows.append(new_row)

    base_cols = ['HBA', 'HBD', 'LogP', 'MW', 'QED', 'SAScore', 'SMILES', 'Similarity', 'TPSA']
    if passing_rows:
        output_df = pd.DataFrame(passing_rows)
        # Ensure all base columns exist
        for c in base_cols:
            if c not in output_df.columns:
                output_df[c] = pd.NA
        # Reorder columns: base cols first, then any extras
        extra = [c for c in output_df.columns if c not in base_cols]
        output_df = output_df[base_cols + extra].reset_index(drop=True)
    else:
        output_df = pd.DataFrame(columns=base_cols)

    return output_df
